<section class="section-heading"><div><span class="section-kicker">THEME COLLECTION · <?=count($library)?> DESIGNS</span><h2>A look for every world</h2><p>Distinct artwork, typography and surfaces. Preview freely, then choose where to apply.</p></div><button type="button" class="edit-theme" data-theme="classic-gold" data-mode="new">＋ Create a theme</button></section>
<div class="theme-grid"><?php foreach($library as $id=>$theme):$custom=isset($state['themes'][$id]);$content=ag_sd_theme_content()[$id] ?? array();$active=array_keys(array_filter($state['scopes'],function($selected)use($id){return $selected===$id;}));?><article class="theme-card <?=$active?'is-active':''?>"><div class="theme-picture"><?=ag_sd_visual_card($theme,$theme['name'])?></div><div class="theme-copy"><div class="card-meta"><span class="step"><?=$custom?'YOUR THEME':'PROTECTED BUILT-IN'?></span><?php if($active):?><span class="active-badge">ACTIVE · <?=ag_h(implode(' / ',$active))?></span><?php endif ?></div><h3><?=ag_h($theme['name'])?></h3><p class="theme-description"><?=ag_h($content['description'] ?? ($id==='current'?'Preserve the current website appearance.':($id==='safe'?'Clear, dependable and independent of custom artwork.':'Your saved palette, artwork and visual treatment.')))?></p><div class="palette" aria-label="Theme palette"><?php foreach($theme['colors'] as $key=>$color):?><span style="background:<?=ag_h($color)?>" title="<?=ag_h($key.': '.$color)?>"></span><?php endforeach ?></div><div class="card-actions"><button type="button" class="secondary preview-theme" data-theme="<?=ag_h($id)?>">Preview</button><button type="button" class="open-apply">Apply</button><?php if(!empty($theme['colors'])):?><button type="button" class="quiet edit-theme" data-theme="<?=ag_h($id)?>" data-mode="duplicate">Duplicate</button><button type="button" class="quiet edit-theme" data-theme="<?=ag_h($id)?>" data-mode="new">Save As</button><?php if($custom):?><button type="button" class="secondary edit-theme" data-theme="<?=ag_h($id)?>" data-mode="edit">Edit</button><button type="button" class="quiet edit-theme" data-theme="<?=ag_h($id)?>" data-mode="rename">Rename</button><?php endif ?><form method="post"><?php $hidden('theme_export')?><input type="hidden" name="theme" value="<?=ag_h($id)?>"><button class="quiet">Export</button></form><?php endif ?></div><details class="apply-options"><summary>Choose where to apply</summary><form method="post" class="apply-theme"><?php $hidden('theme_apply')?><input type="hidden" name="theme" value="<?=ag_h($id)?>"><?php $scopeFields()?><div class="accessibility"><?php foreach(ag_sd_accessibility($theme) as $warning):?><p>⚠ <?=ag_h($warning)?></p><?php endforeach ?></div><button>Apply theme</button></form></details><?php if($custom):?><form method="post" class="remove-theme"><?php $hidden('theme_delete')?><input type="hidden" name="theme" value="<?=ag_h($id)?>"><button class="quiet" <?=in_array($id,$state['scopes'],true)?'disabled title="Apply another theme before removing this one."':''?>>Remove saved theme</button></form><?php endif ?></div></article><?php endforeach ?></div>
<section class="studio-panel"><h2>Bring a theme into your library</h2><p>JSON shares palette, typography and treatments. Complete design ZIPs include artwork and layouts.</p><form method="post" enctype="multipart/form-data"><?php $hidden('theme_import')?><label>Theme file<input type="file" name="themeFile" accept=".json,application/json" required></label><button>Import theme</button></form></section>
